// Replace node-target chunk rebuild to work even when gathering at chunk edges.
function interact(){const n=nearestNode();if(!n){notify('Nothing nearby to gather.');return}harvested.add(n.id);if(n.type==='tree'){player.wood+=2+Math.floor(Math.random()*2);notify('Collected timber.')}else if(n.type==='rock'){player.stone+=1+Math.floor(Math.random()*2);notify('Collected stone.')}else{player.berry+=2+Math.floor(Math.random()*3);notify('Found wild berries.')}const chunk=[...chunks.values()].find(c=>c.nodes.includes(n));if(chunk)rebuildChunk(chunk);updateHUD()}
