function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-lastTick)/1000);lastTick=now;step(dt);for(const f of fires){const s=1+Math.sin(now*.012+f.x)*.12;f.flame.scale.set(s,s, s);f.light.intensity=1.6+Math.sin(now*.008+f.z)*.5}renderer.render(scene,camera);if(Math.floor(now/140)%2===0)drawMap()}
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
document.querySelector('#begin').onclick=()=>{started=true;document.querySelector('#intro').classList.add('hide');canvas.requestPointerLock?.();lastTick=performance.now()};document.querySelector('#restart').onclick=()=>location.reload();
