const keys={};addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyI')togglePanel('inventory');if(e.code==='KeyC')togglePanel('crafting');if(e.code==='KeyE')interact();if(e.code==='KeyF')eat();if(e.code==='Escape'){document.exitPointerLock?.();closePanels()}if(/^Digit[1-4]$/.test(e.code)){selected=Number(e.code.slice(-1))-1;document.querySelectorAll('.slot').forEach((el,i)=>el.classList.toggle('active',i===selected))}});addEventListener('keyup',e=>keys[e.code]=false);
