function panelOpen(){return document.querySelector('.panel.open')!==null}function togglePanel(id){const p=document.getElementById(id),was=p.classList.contains('open');closePanels();if(!was)p.classList.add('open');if(!was)document.exitPointerLock?.()}function closePanels(){document.querySelectorAll('.panel').forEach(p=>p.classList.remove('open'))}document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closePanels);
function notify(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function nearestNode(){let best=null,dist=4.2;for(const c of chunks.values())for(const n of c.nodes){const d=Math.hypot(n.x-player.x,n.z-player.z);if(d<dist){dist=d;best=n}}return best}
function rebuildChunk(c){scene.remove(c.group);chunks.delete(key(c.cx,c.cz));chunks.set(key(c.cx,c.cz),makeChunk(c.cx,c.cz))}
function interact(){const n=nearestNode();if(!n){notify('Nothing nearby to gather.');return}harvested.add(n.id);if(n.type==='tree'){player.wood+=2+Math.floor(Math.random()*2);notify('Collected timber.')}else if(n.type==='rock'){player.stone+=1+Math.floor(Math.random()*2);notify('Collected stone.')}else{player.berry+=2+Math.floor(Math.random()*3);notify('Found wild berries.')}const chunk=[...chunks.values()].find(c=>c.nodes.includes(n));if(chunk)rebuildChunk(chunk);updateHUD()}
function eat(){if(player.berry<=0){notify('No berries in your pack.');return}player.berry--;player.food=clamp(player.food+22,0,100);player.water=clamp(player.water+12,0,100);notify('A handful of sweet berries.');updateHUD()}
document.querySelector('#craftFire').onclick=()=>{if(player.wood<3||player.stone<2){notify('Need 3 timber and 2 stone.');return}player.wood-=3;player.stone-=2;player.fire++;addFire(player.x+Math.sin(player.yaw)*2,player.z-Math.cos(player.yaw)*2);notify('Campfire placed. Stay close to heal.');updateHUD()};document.querySelector('#eatBerry').onclick=eat;
function updateHUD(){document.querySelector('#woodCount').textContent=player.wood;document.querySelector('#stoneCount').textContent=player.stone;document.querySelector('#berryCount').textContent=player.berry;document.querySelector('#fireCount').textContent=player.fire;document.querySelector('#invWood').textContent=player.wood;document.querySelector('#invStone').textContent=player.stone;document.querySelector('#invBerry').textContent=player.berry;document.querySelector('#invFire').textContent=player.fire;for(const [id,val] of [['health',player.health],['food',player.food],['water',player.water]]){document.querySelector(`#${id}Bar`).style.width=val+'%';document.querySelector(`#${id}Num`).textContent=Math.ceil(val);document.querySelector(`#${id}Bar`).style.background=val<25?'#d77d59':'#c3dc91'}document.querySelector('#coords').textContent=`N ${String(Math.round(player.z)).padStart(3,'0')} · E ${String(Math.round(player.x)).padStart(3,'0')}`}
function setupWorld(){updateChunks();camera.position.set(player.x,heightAt(player.x,player.z)+1.72,player.z)}
function drawMap(){mapCtx.clearRect(0,0,136,136);mapCtx.fillStyle='#283b2e';mapCtx.fillRect(0,0,136,136);for(let z=0;z<136;z+=4)for(let x=0;x<136;x+=4){const wx=player.x+(x-68)*1.5,wz=player.z+(z-68)*1.5,h=hash(Math.floor(wx/8),Math.floor(wz/8),2);mapCtx.fillStyle=h>.78?'#64764d':h>.52?'#485f42':'#354c3c';mapCtx.fillRect(x,z,3,3)}for(const f of fires){const dx=(f.x-player.x)/1.5,dy=(f.z-player.z)/1.5;if(Math.abs(dx)<64&&Math.abs(dy)<64){mapCtx.fillStyle='#f0a85c';mapCtx.beginPath();mapCtx.arc(68+dx,68+dy,2.4,0,7);mapCtx.fill()}}mapCtx.save();mapCtx.translate(68,68);mapCtx.rotate(-player.yaw);mapCtx.fillStyle='#e2edbd';mapCtx.beginPath();mapCtx.moveTo(0,-6);mapCtx.lineTo(4,5);mapCtx.lineTo(0,3);mapCtx.lineTo(-4,5);mapCtx.fill();mapCtx.restore()}
function setTime(dt){player.time+=dt*.035;if(player.time>=24){player.time-=24;player.day++;document.querySelector('#dayText').textContent=String(player.day).padStart(2,'0')}const hour=Math.floor(player.time),min=Math.floor((player.time-hour)*60);document.querySelector('#timeText').textContent=`${String(hour).padStart(2,'0')}:${String(min).padStart(2,'0')}`;const sunY=Math.sin((player.time-6)/12*Math.PI);sun.position.set(-55,Math.max(8,80*sunY),-25);const night=clamp((sunY+.15)/.5,0,1);hemi.intensity=.55+night*1.65;sun.intensity=.15+night*3.1;scene.background.set(night<.35?'#26394a':'#a9c5c6');scene.fog.color.set(night<.35?'#26394a':'#a9c5c6');document.querySelector('#weatherText').textContent=sunY<0?'NIGHT':'CLEAR'}
function step(dt){if(!started||panelOpen()||!player.active)return;const fw=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);let dx=0,dz=0;if(fw||side){const m=Math.hypot(fw,side),f=fw/m,s=side/m,cos=Math.cos(player.yaw),sin=Math.sin(player.yaw);dx=(sin*f+cos*s)*player.speed*dt;dz=(-cos*f+sin*s)*player.speed*dt;player.x+=dx;player.z+=dz}camera.position.set(player.x,heightAt(player.x,player.z)+1.72,player.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');player.food=Math.max(0,player.food-dt*.032);player.water=Math.max(0,player.water-dt*.048);if(player.food===0||player.water===0)player.health=Math.max(0,player.health-dt*.5);for(const f of fires)if(Math.hypot(f.x-player.x,f.z-player.z)<5)player.health=Math.min(100,player.health+dt*.35);if(Math.floor(player.x/CHUNK)!==Math.floor((player.x-dx)/CHUNK)||Math.floor(player.z/CHUNK)!==Math.floor((player.z-dz)/CHUNK))updateChunks();setTime(dt);updateHUD();const n=nearestNode(),label=document.querySelector('#interact');if(n){label.textContent=`[ E ] GATHER ${n.type.toUpperCase()}`;label.classList.add('show')}else label.classList.remove('show');if(player.health<=0){player.active=false;document.querySelector('#deathReason').textContent=player.water<=0?'The thirst became too much.':'The wilderness took its toll.';document.querySelector('#gameover').classList.add('show')}}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-lastTick)/1000);lastTick=now;step(dt);for(const f of fires){const s=1+Math.sin(now*.012+f.x)*.12;f.flame.scale.set(s,s,s);f.light.intensity=1.6+Math.sin(now*.008+f.z)*.5}renderer.render(scene,camera);if(Math.floor(now/140)%2===0)drawMap()}
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});document.querySelector('#begin').onclick=()=>{started=true;document.querySelector('#intro').classList.add('hide');canvas.requestPointerLock?.();lastTick=performance.now()};document.querySelector('#restart').onclick=()=>location.reload();document.addEventListener('visibilitychange',()=>{if(document.hidden)document.exitPointerLock?.()});setupWorld();updateHUD();requestAnimationFrame(animate);

