function updateJoystick(e){
  e.preventDefault();
  const r=joystick.getBoundingClientRect();
  let x=e.clientX-(r.left+r.width/2);
  let y=e.clientY-(r.top+r.height/2);
  const max=Math.min(r.width,r.height)*.34;
  const d=Math.hypot(x,y);
  if(d>max){x=x/d*max;y=y/d*max}
  mobileMove.x=-x/max;
  mobileMove.y=y/max;
  stick.style.transform=`translate3d(${x}px,${y}px,0)`;
}
function resetJoystick(){joyId=null;mobileMove.x=mobileMove.y=0;stick.style.transform='translate3d(0,0,0)'}
joystick.addEventListener('pointerdown',e=>{e.preventDefault();joyId=e.pointerId;joystick.setPointerCapture(e.pointerId);updateJoystick(e)});
joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyId){e.preventDefault();updateJoystick(e)}});
joystick.addEventListener('pointerup',e=>{if(e.pointerId===joyId){e.preventDefault();resetJoystick()}});
joystick.addEventListener('pointercancel',resetJoystick);
joystick.addEventListener('lostpointercapture',resetJoystick);

